  async function loadCreatorRanking(){if(!sb||!S.user)return;const {data,error}=await sb.rpc('qr_creator_leaderboard',{p_limit:50});if(!error)S.qrCreatorRows=data||[];render()}
  function creatorRanking(){if(!S.qrCreatorRows){setTimeout(loadCreatorRanking,0);return `<section class="qr-ranking-page"><div class="card pad center">Carregando ranking de criadores…</div></section>`}return `<section class="qr-ranking-page"><div class="qr-page-title"><div><h1>👑 Ranking de Criadores</h1><p>Os quizzes mais bem avaliados pela comunidade.</p></div></div><div class="qr-ranking-list full">${(S.qrCreatorRows||[]).map((r,i)=>`<button class="qr-rank-row large" data-profile="${r.user_id}"><span class="qr-rank-num">${i+1}</span>${profileAvatarMarkup(r,'avatar qr-rank-avatar')}<div><b>${esc(r.username||'Jogador')}</b><small>${Number(r.quizzes||0)} quizzes • ${Number(r.plays||0)} partidas</small><em>⭐ ${Number(r.avg_rating||0).toFixed(2)} (${Number(r.rating_count||0)} avaliações)</em></div><strong>${i<3?['🥇','🥈','🥉'][i]:'🏅'}</strong></button>`).join('')||'<div class="classic-empty">Ainda não há criadores classificados.</div>'}</div><button class="secondary" data-go="modes">← VOLTAR AOS MODOS</button></section>`}
  async function claimDailyReward(chest=false){if(!sb)return;const {data,error}=await sb.rpc('qr_claim_daily_reward',{p_chest:chest});if(error)return alert(error.message);if(data?.item_id)alert(`🎁 Você ganhou ${Number(data.coins||0)} Coins e um item raro!`);else alert(`${chest?'🎁 Baú aberto! ':'🔥 Sequência registrada! '}+${Number(data?.coins||0)} Coins`);await loadProfile();await loadModeData();render()}
  async function loadImpossibleQuestion(){if(!sb||!S.qrImpossible?.question_id)return;const {data}=await sb.from('questions').select('id,question_text,options,image_url').eq('id',S.qrImpossible.question_id).maybeSingle();S.qrImpossibleQuestion=data||null;render()}
