  async function openSuddenRoom(){
    if(!sb||!S.user)return alert('Faça login para jogar.');
    const category=S.category||'Geral';
    const {data,error}=await sb.rpc('qr_find_sudden_room',{p_category:category});
    if(error)return alert(error.message||'Não foi possível encontrar uma sala.');
    S.qrSuddenRoom=data;await loadSuddenRoom(data);go('sudden');startSuddenSync();
  }
  async function joinSuddenByCode(code){
    if(!sb||!code)return;
    const {data,error}=await sb.rpc('qr_join_sudden_room',{p_code:code});if(error)return alert(error.message);S.qrSuddenRoom=data;await loadSuddenRoom(data);go('sudden');startSuddenSync();
  }
  async function loadSuddenRoom(id){
    if(!sb||!id)return;
    const [{data:r},{data:p}]=await Promise.all([sb.from('qr_sudden_rooms').select('*').eq('id',id).single(),sb.from('qr_sudden_players').select('room_id,user_id,score,status,joined_at,last_answer_question').eq('room_id',id)]);
    const ids=(p||[]).map(x=>x.user_id);let people={};if(ids.length){const {data:ps}=await sb.from('profiles').select('id,username,display_name,avatar_url,main_title_id,premium_vip,premium_vip_until,premium_frame,premium_effect,premium_theme,premium_avatar,premium_title,premium_badge').in('id',ids);(ps||[]).forEach(x=>people[x.id]=x)}
    S.qrSuddenRoom=r;S.qrSuddenPlayers=(p||[]).map(x=>({...x,profile:people[x.user_id]||{username:'Jogador'}}));
    if(r?.status==='running'){
      const ids=r.question_ids||[];if(ids.length){const {data:q}=await sb.from('questions').select('id,question_text,options,correct_index,image_url').in('id',ids);const map=new Map((q||[]).map(x=>[String(x.id),x]));S.qrSuddenQuestions=ids.map(x=>map.get(String(x))).filter(Boolean);}
    }
    if(r?.status==='running')startSuddenTimer();
  }
  function startSuddenSync(){
    clearInterval(S.qrSuddenSync);S.qrSuddenSync=setInterval(async()=>{if(S.route!=='sudden'||!S.qrSuddenRoom)return;await loadSuddenRoom(S.qrSuddenRoom.id);render();},1000);
  }
  function startSuddenTimer(){clearInterval(S.qrSuddenTimer);if(!S.qrSuddenRoom||S.qrSuddenRoom.status!=='running')return;const started=Number(S.qrSuddenRoom.state?.question_started_at||0)*1000;const limit=Number(S.qrSuddenRoom.state?.question_seconds||15);S.qrSuddenTimer=setInterval(async()=>{if(S.route!=='sudden'||!S.qrSuddenRoom)return;const left=Math.max(0,limit-Math.floor((Date.now()-started)/1000));const el=$('#suddenTimer');if(el)el.textContent=String(left);if(left<=0){clearInterval(S.qrSuddenTimer);S.qrSuddenTimer=null;const me=S.qrSuddenPlayers.find(p=>String(p.user_id)===String(S.user.id));if(me?.status==='active'&&me.last_answer_question!==Number(S.qrSuddenRoom.current_question||0)){await sb.rpc('qr_submit_sudden_answer',{p_room_id:S.qrSuddenRoom.id,p_question_index:Number(S.qrSuddenRoom.current_question||0),p_answer_index:-1});await loadSuddenRoom(S.qrSuddenRoom.id);render();}}},200);}
  async function startSudden(){if(!sb||!S.qrSuddenRoom)return;const {error}=await sb.rpc('qr_start_sudden_room',{p_room_id:S.qrSuddenRoom.id});if(error)return alert(error.message);await loadSuddenRoom(S.qrSuddenRoom.id);render();}
  async function answerSudden(i){
    if(!sb||!S.qrSuddenRoom||S.qrSuddenRoom.status!=='running')return;
    const qi=Number(S.qrSuddenRoom.current_question||0);const btns=$$('.sudden-answer');btns.forEach(b=>b.disabled=true);
    const {data,error}=await sb.rpc('qr_submit_sudden_answer',{p_room_id:S.qrSuddenRoom.id,p_question_index:qi,p_answer_index:Number(i)});
    if(error){alert(error.message);return}if(data?.correct)sound('correct');else sound('wrong');await loadSuddenRoom(S.qrSuddenRoom.id);render();
  }
  function suddenDeath(){
    const r=S.qrSuddenRoom;const players=S.qrSuddenPlayers||[];
    if(!r)return `<section class="qr-sudden-page"><div class="card pad center"><h1>💀 Morte Súbita</h1><p>Até 8 jogadores. Procure adversários ou crie uma sala privada.</p><button class="qr-yellow-btn" id="suddenFind">🔎 PROCURAR ADVERSÁRIOS</button><button class="secondary" id="suddenCreate">➕ CRIAR SALA</button><div class="sudden-code-form"><input id="suddenCode" maxlength="6" placeholder="Código da sala"><button class="secondary" id="suddenJoin">ENTRAR</button></div></div></section>`;
    if(r.status==='waiting')return `<section class="qr-sudden-page"><div class="qr-sudden-head"><div><span>💀 MORTE SÚBITA</span><h1>Sala ${esc(r.code)}</h1><p>${esc(r.category)} • máximo ${r.max_players} jogadores</p></div><button class="secondary" id="suddenLeave">SAIR</button></div><div class="sudden-room-share"><b>Convide seus adversários</b><strong>${esc(r.code)}</strong><small>Compartilhe este código para seus amigos entrarem.</small><button class="secondary" id="shareSuddenRoom">📤 COMPARTILHAR SALA</button></div><div class="sudden-players">${players.map((p,i)=>{const prof=p.profile||{};return `<div class="sudden-player">${profileAvatarMarkup(p.user_id===S.user.id?S.profile:prof,'avatar mini')}<b>${p.user_id===S.user.id?'Você':esc(prof.username||prof.display_name||'Jogador')}</b><span>${p.status==='active'?'PRONTO':'ELIMINADO'}</span></div>`}).join('')}</div>${r.host_id===S.user.id?`<button class="qr-yellow-btn" id="suddenStart" ${players.length<2?'disabled':''}>🚀 INICIAR PARTIDA (${players.length}/8)</button>`:`<div class="notice">Aguardando o criador iniciar a partida…</div>`}</section>`;
    if(r.status==='finished')return `<section class="qr-sudden-page"><div class="sudden-result"><span>🏆</span><h1>Fim da Morte Súbita</h1><p>Vencedor: <b>${players.find(p=>String(p.user_id)===String(r.winner_id))?'🏆 Jogador vencedor':'Jogador'}</b></p><button class="qr-yellow-btn" id="suddenAgain">JOGAR NOVAMENTE</button></div></section>`;
    const qi=Number(r.current_question||0),q=S.qrSuddenQuestions[qi];const me=players.find(p=>String(p.user_id)===String(S.user.id));
    if(!q)return `<section class="qr-sudden-page"><div class="card pad center">Carregando pergunta…</div></section>`;
    return `<section class="qr-sudden-page"><div class="sudden-battle-head"><div><b>💀 MORTE SÚBITA</b><small>PERGUNTA ${qi+1} DE ${S.qrSuddenQuestions.length}</small></div><strong id="suddenTimer">${Number((r.state||{}).question_seconds||15)}</strong></div><div class="sudden-scoreboard">${players.map(p=>`<span class="${p.status==='eliminated'?'eliminated':''}">${p.user_id===S.user.id?'Você':esc(p.profile?.username||'👤')} ${p.score} ${p.status==='eliminated'?'💀':''}</span>`).join('')}</div><div class="sudden-question"><span>ERROU = ELIMINADO</span><h2>${esc(q.question_text)}</h2>${q.image_url?`<img src="${esc(q.image_url)}" alt="">`:''}</div><div class="sudden-answers">${(q.options||[]).map((a,i)=>`<button class="sudden-answer" data-sudden-answer="${i}" ${me?.status==='eliminated'||me?.last_answer_question===qi?'disabled':''}><span>${'ABCD'[i]}</span>${esc(a)}</button>`).join('')}</div>${me?.status==='eliminated'?'<div class="notice">💀 Você foi eliminado. Aguarde o vencedor.</div>':(me?.last_answer_question===qi?'<div class="notice">✓ Resposta enviada. Aguarde os outros jogadores.</div>':'')}</section>`;
  }

  function view(){if(!S.user&&!['login','signup'].includes(S.route))return login();if(S.route==='login')return login();if(S.route==='signup')return signup();if(S.route==='home')return home();if(S.route==='modes')return modesHub();if(S.route==='sudden')return suddenDeath();if(S.route==='creator-ranking')return creatorRanking();if(S.route==='season')return seasonPass();if(S.route==='tournaments')return tournamentsPage();if(S.route==='events')return eventsPage();if(S.route==='impossible')return impossiblePage();if(S.route==='store')return premiumStore();if(S.route==='categories')return categories();if(S.route==='topic')return topic();if(S.route==='contribute')return contribute();if(S.route==='match')return match();if(S.route==='game')return game();if(S.route==='async-game')return asyncGame();if(S.route==='result')return result();if(S.route==='ranking')return rank();if(S.route==='profile')return profile();if(S.route==='friends')return friends();if(S.route==='chat')return chat();if(S.route==='support')return support();if(S.route==='news')return news();if(S.route==='notifications')return notificationsView();if(S.route==='admin')return admin();return achievements()}

  function login(){return `<div class="card pad auth-card"><div class="bolt auth-logo">ϟ</div><h1>Entrar no Q-Rival</h1><p class="subtitle">Use seu nome de usuário ou e-mail para entrar.</p><form id="loginForm" class="form" style="text-align:left;margin-top:20px"><label>Nome de usuário ou e-mail</label><input id="identifier" required autocomplete="username" placeholder="usuario ou seu@email.com"><label>Senha</label><input id="password" type="password" required autocomplete="current-password" placeholder="••••••••"><button class="primary">ENTRAR</button></form><button class="secondary" id="signupGo">CRIAR CONTA</button>${!ready?'<div class="notice" style="margin-top:12px">Supabase não configurado. Configure <b>config.js</b> para entrar no multiplayer.</div>':''}</div>`}
  function signup(){return `<div class="card pad"><div class="title">Criar conta</div><div class="subtitle">Seu nome de usuário será único e aparecerá no ranking e para seus amigos.</div><form id="signupForm" class="form" style="margin-top:18px"><label>Nome de usuário</label><input id="username" required minlength="3" maxlength="20" pattern="[A-Za-z0-9_]{3,20}" autocomplete="username" placeholder="Ex.: Jogador123"><small class="muted">Use de 3 a 20 caracteres: letras, números e _</small><label>E-mail</label><input id="email" type="email" required autocomplete="email" placeholder="seu@email.com"><label>Senha</label><input id="password" type="password" required minlength="6" autocomplete="new-password" pattern="[A-Za-z0-9]{6,}" placeholder="mínimo 6 caracteres, letras e números"><button class="primary">CRIAR CONTA</button></form><button class="secondary" id="loginGo">JÁ TENHO CONTA</button></div>`}
  async function loadEngagementData(){
    if(!sb||!S.user)return;
    try{
      const now=new Date(), iso=now.toISOString();
      const weekAgo=new Date(Date.now()-7*86400000).toISOString();
      const [ev,mi,se,lb,tr,gr]=await Promise.all([
        sb.from('qr_events').select('id,name,description,icon,event_type,start_at,end_at,active,category,xp_multiplier,coin_reward,reward_item_id,rules').eq('active',true).lte('start_at',iso).gte('end_at',iso).order('start_at',{ascending:true}),
        sb.from('qr_missions').select('id,title,description,icon,criteria_type,target,reward_xp,reward_coins,reward_item_id,active,start_at,end_at,category').eq('active',true).lte('start_at',iso).gte('end_at',iso).order('start_at'),
        sb.from('qr_seasons').select('*').eq('active',true).lte('start_at',iso).gte('end_at',iso).order('start_at',{ascending:false}).limit(1).maybeSingle(),
        sb.rpc('qr_weekly_leaderboard'),
        sb.from('qr_tournaments').select('id,name,description,icon,start_at,end_at,status,max_players,reward_xp,reward_coins,reward_item_id,category').in('status',['open','running']).order('start_at'),
        sb.from('game_results').select('created_at,won,outcome,score,category').eq('user_id',S.user.id).gte('created_at',weekAgo).order('created_at',{ascending:false}).limit(200)
      ]);
      S.qrEvents=ev.error?[]:(ev.data||[]);S.qrMissions=mi.error?[]:(mi.data||[]);S.qrSeason=se.error?null:se.data;S.qrLeagueRows=lb.error?[]:(lb.data||[]);S.qrTournamentRows=tr.error?[]:(tr.data||[]);
      const rows=gr.error?[]:(gr.data||[]);S.qrStats=computeMissionStats(rows);S.qrWeekRows=rows;
    }catch(e){console.warn('engagement',e)}
  }
  function computeMissionStats(rows){
    const today=new Date();today.setHours(0,0,0,0);const day=rows.filter(r=>new Date(r.created_at)>=today);let run=0,best=0;
    for(const r of [...rows].sort((a,b)=>new Date(a.created_at)-new Date(b.created_at))){if(r.won){run++;best=Math.max(best,run)}else run=0}
    let currentStreak=0; for(const r of [...rows].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at))){if(r.won)currentStreak++;else break}
    return {games:day.length,wins:day.filter(r=>r.won).length,score:day.reduce((a,r)=>a+Number(r.score||0),0),streak:best,currentStreak};
  }
  function eventRewardName(id){return id?(S.premiumItems||[]).find(x=>String(x.id)===String(id))?.name||'Recompensa':null}
  function engagementHome(){
    const p=S.profile||{}, events=S.qrEvents||[], missions=S.qrMissions||[], stats=S.qrStats||{games:0,wins:0,streak:0,score:0};
    const progress=m=>{const v=Number(stats[m.criteria_type]||0);return Math.min(Number(m.target||1),v)};
    const ev=events[0], tr=(S.qrTournamentRows||[])[0];
    const league=String((S.qrLeagueRows||[]).find(x=>String(x.user_id)===String(S.user?.id))?.league||'Bronze');
    const leaguePts=Number((S.qrLeagueRows||[]).find(x=>String(x.user_id)===String(S.user?.id))?.points||0);
    return `<div class="qr-engagement-grid"><div class="qr-engagement-card event-card">${ev?`<div class="eng-icon">${esc(ev.icon||'🔥')}</div><div><span>🔥 EVENTO ATIVO</span><h3>${esc(ev.name)}</h3><p>${esc(ev.description||'Participe e acumule recompensas.')}</p><small>${ev.category?`Categoria: ${esc(ev.category)} • `:''}até ${new Date(ev.end_at).toLocaleString('pt-BR')}</small></div>`:'<div><span>🔥 EVENTOS</span><h3>Nenhum evento ativo</h3><p>O administrador ainda não abriu um evento.</p></div>'}</div><div class="qr-engagement-card mission-card"><div class="eng-card-head"><b>🎯 MISSÕES DE HOJE</b><button class="secondary" data-go="achievements">🏆 Conquistas</button></div>${missions.length?missions.slice(0,3).map(m=>{const v=progress(m);const pct=Math.min(100,Math.round(v/Math.max(1,Number(m.target))*100));const done=v>=Number(m.target||1); return `<div class="eng-mission"><div><b>${esc(m.icon||'🎯')} ${esc(m.title)}</b><small>${esc(m.description||'')} • ${v}/${Number(m.target)}</small></div><i><span style="width:${pct}%"></span></i><strong>+${Number(m.reward_xp||0)} XP${Number(m.reward_coins||0)?` • +${Number(m.reward_coins)} ⚡`:''}</strong>${done?`<button class="secondary claimMission" data-id="${esc(m.id)}">RESGATAR</button>`:''}</div>`}).join(''):'<div class="muted">Nenhuma missão configurada para hoje.</div>'}</div><div class="qr-engagement-card league-card"><div class="eng-icon">🏆</div><div><span>SUA LIGA</span><h3>${esc(league)}</h3><p>${leaguePts.toLocaleString('pt-BR')} pontos nesta semana.</p><button class="secondary" data-go="ranking">VER RANKING</button></div></div><div class="qr-engagement-card streak-card"><div class="eng-icon">🔥</div><div><span>SEQUÊNCIA</span><h3>${Number(p.current_streak||stats.streak||0)} vitórias</h3><p>Jogue novamente para aumentar sua sequência.</p></div></div>${tr?`<div class="qr-engagement-card tournament-card"><div class="eng-icon">🏟️</div><div><span>TORNEIO</span><h3>${esc(tr.name)}</h3><p>${esc(tr.description||'Compita pelo topo.')}</p><button class="qr-yellow-btn" data-tournament-id="${esc(tr.id)}">PARTICIPAR</button></div></div>`:''}</div>`;
  }
  function home(){
    const p=S.profile||{};
    const name=esc(p.username||'Jogador');
    const coins=Number(p.coins||0).toLocaleString('pt-BR');
    return `<section class="qr-home-standalone">
      <div class="qr-home-welcome">
        <div class="qr-home-badge">⚡</div>
        <h1>Bem-vindo ao Q-Rival</h1>
        <p>Olá, <b>${name}</b>! Escolha uma opção no menu para abrir cada área separadamente.</p>
        <div class="qr-home-actions">
          <button class="qr-yellow-btn" data-go="categories">▶ JOGAR AGORA</button>
          <button class="secondary" data-go="ranking">🏆 VER RANKING</button><button class="secondary" data-go="modes">⚔️ MODOS DE JOGO</button>
        </div>
      </div>
      <div class="qr-home-info">
        <div><span>⚡</span><b>${coins}</b><small>QuizCoins</small></div>
        <div><span>🎯</span><b>Nível ${p.level||1}</b><small>Seu nível atual</small></div>
        <div><span>🔥</span><b>${Number(p.current_streak||S.qrStats?.currentStreak||0)}</b><small>Melhor sequência</small></div>
      </div>${engagementHome()}
    </section>`;
  }

  function contribute(){
    const rows=Array.from({length:10},(_,i)=>`<div class="category-question-card">
      <div class="category-question-head"><b>PERGUNTA ${i+1}</b><span>4 alternativas</span></div>
      <label>Pergunta</label>
      <textarea id="cqText${i}" required maxlength="300" rows="2" placeholder="Digite a pergunta..."></textarea>
      <div class="cq-options-grid">
        <input id="cq0_${i}" required maxlength="180" placeholder="A — resposta">
        <input id="cq1_${i}" required maxlength="180" placeholder="B — resposta">
        <input id="cq2_${i}" required maxlength="180" placeholder="C — resposta">
        <input id="cq3_${i}" required maxlength="180" placeholder="D — resposta">
      </div>
      <label>Resposta correta</label>
      <select id="cqCorrect${i}" required>
        <option value="0">A</option><option value="1">B</option><option value="2">C</option><option value="3">D</option>
      </select>
      <label>Tipo da pergunta</label>
      <select id="cqType${i}" class="cq-type"><option value="text">Somente texto</option><option value="image">Texto + imagem</option></select>
      <div id="cqImageWrap${i}" class="cq-image-wrap" hidden>
        <label class="upload-image-label" for="cqImage${i}">🖼️ Escolher imagem</label>
        <input id="cqImage${i}" type="file" accept="image/*" hidden>
        <div id="cqImageName${i}" class="muted">Nenhuma imagem selecionada</div>
        <img id="cqImagePreview${i}" class="cq-image-preview" alt="Prévia" hidden>
      </div>
    </div>`).join('');
    return `<section class="contribute-page">
      <div class="title">🎯 Criar novo Quiz</div>
      <p class="subtitle">Crie seu próprio tópico com 10 perguntas. O conteúdo será enviado para análise do administrador antes de ficar público.</p>
      <form id="categoryPackageForm" class="form">
        <div class="card pad contribute-intro">
          <label>Nome do quiz/categoria</label>
          <input id="packageCatName" required maxlength="50" placeholder="Ex.: Curiosidades do Futebol">
          <label>Ícone</label>
          <input id="packageCatIcon" maxlength="8" value="🎯" placeholder="🌐">
          <label>Descrição</label>
          <textarea id="packageCatDesc" maxlength="180" rows="3" placeholder="Sobre o seu quiz..."></textarea>
        </div>
        <div class="contribute-questions">${rows}</div>
        <div class="contribute-submit-bar">
          <button type="button" class="secondary" id="backCategories">← VOLTAR</button>
          <button type="submit" class="primary" id="submitCategoryPackage">ENVIAR QUIZ PARA REVISÃO</button>
        </div>
      </form>
    </section>`;
  }

  function categories(){
    const cats=S.categories.length?S.categories:catFallback(); const term=S.categorySearch.trim().toLowerCase();
    const filtered=cats.filter(c=>!term||c.name.toLowerCase().includes(term)||(c.description||'').toLowerCase().includes(term));
    const mains=filtered.filter(c=>!c.parent_id), subs=filtered.filter(c=>c.parent_id);
    const renderCat=(c,i)=>`<button class="cat classic-cat ${catClass(i)} ${c.cover_url?'has-cat-cover':''}" data-cat="${esc(c.name)}" style="${c.cover_url?`--cat-cover:url('${esc(c.cover_url)}')`:''}"><span>${c.cover_url?`<img src="${esc(c.cover_url)}" alt="" loading="lazy">`:esc(c.icon||'✦')}</span><b>${esc(c.name)}</b><small>Nível ${topicLevel(c.name)} • ⭐ ${(S.qrQuizRatings?.[String(c.id)]?.avg||0).toFixed(1)} (${S.qrQuizRatings?.[String(c.id)]?.count||0})</small></button>`;
    return `<section class="classic-page"><div class="classic-banner"><b>Escolha seu próximo desafio</b><span>Compita em tópicos e suba de nível em cada um deles.</span></div><div class="searchbar classic-search"><input id="categorySearch" value="${esc(S.categorySearch)}" placeholder="🔎 Buscar tópicos"><button id="clearCategorySearch" type="button">×</button></div><div class="classic-section-head"><b>Novos e atualizados</b><button id="contributeGo">CRIAR</button></div><div class="topic-grid">${mains.slice(0,12).map(renderCat).join('')}</div>${subs.length?`<div class="classic-section-head"><b>Subtópicos</b></div><div class="topic-grid">${subs.map(renderCat).join('')}</div>`:''}<div class="classic-section-head"><b>Todos os tópicos</b></div><div class="topic-list">${filtered.slice(0,60).map((c,i)=>`<button class="topic-list-row" data-cat="${esc(c.name)}"><span class="topic-icon ${catClass(i)}">${esc(c.icon||'✦')}</span><span><b>${esc(c.name)}</b><small>${c.parent_id?'Subtópico':'Tópico'} • Nível ${topicLevel(c.name)}</small></span><strong>›</strong></button>`).join('')||'<div class="classic-empty">Nenhum tópico encontrado.</div>'}</div></section>`;
  }
  function xpLevelFromXp(xp){return Math.min(1000,Math.max(1,1+Math.floor(Math.max(0,Number(xp)||0)/100)))}
  function xpProgressValue(xp){const n=Math.max(0,Number(xp)||0);return n>=99900?100:n%100}
  function topicLevel(category){
    const rows=(S.recentRows||[]).filter(r=>r.category===category); const xp=rows.reduce((n,r)=>n+Number(r.score||0),0); return xpLevelFromXp(xp);
  }
  async function loadRecentResults(){if(!sb||!S.user)return;const {data}=await sb.from('game_results').select('category,score,won,outcome,created_at').eq('user_id',S.user.id).order('created_at',{ascending:false}).limit(40);S.recentRows=data||[];render()}
  async function loadTopicData(){if(!sb||!S.user||!S.topicCategory)return;const [{data:mine},{data:ranking}]=await Promise.all([sb.from('game_results').select('score,won,created_at').eq('user_id',S.user.id).eq('category',S.topicCategory),sb.rpc('get_topic_ranking',{p_category:S.topicCategory,p_limit:20})]);const rows=mine||[];const xp=rows.reduce((n,r)=>n+Number(r.score||0),0);S.topicStats={xp,games:rows.length,wins:rows.filter(r=>r.won).length,losses:rows.filter(r=>!r.won).length,level:xpLevelFromXp(xp)};S.topicRows=ranking||[];render()}
  function topic(){if(!S.topicStats){setTimeout(loadTopicData,0);return `<section class="topic-detail loading-topic"><div class="rings small-rings"><div class="big">ϟ</div></div><div class="muted">Carregando tópico...</div></section>`}const t=S.topicStats;const pct=Math.min(100,(xpProgressValue(t.xp)/100)*100);return `<section class="topic-detail"><div class="topic-cover ${S.categories.find(c=>c.name===S.topicCategory)?.cover_url?'has-topic-cover':''}" style="${S.categories.find(c=>c.name===S.topicCategory)?.cover_url?`--topic-cover:url('${esc(S.categories.find(c=>c.name===S.topicCategory).cover_url)}')`:''}"><span class="topic-cover-icon">${S.categories.find(c=>c.name===S.topicCategory)?.cover_url?`<img src="${esc(S.categories.find(c=>c.name===S.topicCategory).cover_url)}" alt="">`:'✦'}</span><h1>${esc(S.topicCategory)}</h1><p>Nível ${t.level}</p></div><button class="classic-big-play" id="topicPlay">JOGAR AGORA <span>⚡</span></button><div class="topic-progress"><div class="progress-head"><b>Nível ${t.level}</b><span>${xpProgressValue(t.xp)} / 100 XP</span></div><div class="topic-progress-bar"><i style="width:${pct}%"></i></div></div><div class="classic-stat-grid"><div><b>${t.games}</b><small>JOGOS</small></div><div><b>${t.wins}</b><small>VITÓRIAS</small></div><div><b>${t.losses}</b><small>DERROTAS</small></div><div><b>${t.games?Math.round(t.wins/t.games*100):0}%</b><small>VITÓRIAS</small></div></div><div class="classic-section-head"><b>Ranking de ${esc(S.topicCategory)}</b><button id="topicRanking">VER RANKING</button></div><div class="list topic-ranking">${(S.topicRows||[]).slice(0,10).map((r,i)=>`<button class="row player-row" data-profile="${r.id}"><b>#${i+1}</b>${profileAvatarMarkup(r,'avatar mini')}${playerTitleBelowMarkup(r,'rank-title-below')}<div><b>${esc(r.username||r.display_name||'Jogador')}</b><div class="muted">Nível ${r.level||1} • ${r.wins||0} vitórias</div></div><strong>${r.topic_xp||0}</strong></button>`).join('')||'<div class="classic-empty">Ainda não há jogadores classificados neste tópico.</div>'}</div><div class="quiz-rating-box"><b>⭐ Avalie este quiz</b><div class="rating-stars">${[1,2,3,4,5].map(n=>`<button type="button" data-rate="${n}">${n}★</button>`).join('')}</div><textarea id="quizReview" maxlength=300 placeholder="O que achou deste quiz?"></textarea><button class="secondary" id="submitQuizRating">ENVIAR AVALIAÇÃO</button></div><button class="secondary" id="backTopics">← VOLTAR AOS TÓPICOS</button></section>`}


  function premiumLoad(){try{const raw=localStorage.getItem('quizup_premium');if(raw)S.premium={...S.premium,...JSON.parse(raw)}}catch(e){}}
  function premiumSave(){localStorage.setItem('quizup_premium',JSON.stringify(S.premium))}
  function premiumActive(){return S.premium?.active||{}}
  function isVip(profile=S.profile){return !!profile?.premium_vip_until&&new Date(profile.premium_vip_until).getTime()>Date.now()}
  function premiumBadge(){return isVip(S.profile)?'<em class="premium-badge">VIP</em>':''}
  function emblemColor(profile=S.profile){
    const c=activeCosmeticsFor(profile||{}); const item=premiumItemById(c?.frame||c?.badge||profile?.premium_frame||profile?.premium_badge);
    const raw=String(item?.name||item?.cat||'').toLowerCase();
    if(/fogo|fire|vermelho|red/.test(raw))return '#ff5a36';
    if(/água|agua|water|azul|blue/.test(raw))return '#18cfff';
    if(/terra|earth|verde|green/.test(raw))return '#b9f23a';
    if(/ar|air|prata|silver|branco|white/.test(raw))return '#d9e8ff';
    if(/trevas|dark|roxo|purple/.test(raw))return '#d34cff';
    if(/luz|light|dour|gold|amarelo|yellow/.test(raw))return '#ffd21a';
    return '#ffd21a';
  }
  function xpColorStyle(profile=S.profile){return `--xp-color:${esc(emblemColor(profile))};`}
  function getMainTitleObj(profile=S.profile){
    if(!profile)return null;
    // Administradores sempre usam o título de sistema "Administrador" como principal.
    // Ele não depende do inventário e nunca deve ser substituído por um título comprado.
    if(profile.role==='admin')return {id:'__admin__',title_id:'__admin__',name:'Administrador',icon:'👑',description:'Título exclusivo da equipe administrativa.',effect_style:'gold',active:true,is_main:true};
    if(profile.main_title?.name)return profile.main_title;
    if(Array.isArray(profile.owned_titles)){const own=profile.owned_titles.find(x=>x.is_main);if(own)return own;}
    // S.userTitles pertence somente ao jogador logado. Nunca use essa lista para outro perfil.
    if(profile.id===S.user?.id && Array.isArray(S.userTitles)){
      if(profile.main_title_id){const t=S.userTitles.find(x=>String(x.title_id)===String(profile.main_title_id));if(t)return t;}
      return S.userTitles.find(t=>t.is_main)||null;
    }
    return null;
  }
  function getSecondaryTitleObj(profile=S.profile){
    if(!profile)return null;
    if(profile.role!=='admin')return null;
    const raw=String(profile.premium_title||'');
    if(!raw)return null;
    const item=premiumItemById(raw);
    return item?.kind==='title'?item:null;
  }
  function titlePairMarkup(profile, cls='premium-game-title-image'){
    const main=getMainTitleObj(profile);
    return main?`<div class="title-slot title-slot-main">${titleVisualMarkup(main,cls)}</div>`:'';
  }
  function getMainTitle(profile=S.profile){
    const obj=getMainTitleObj(profile);
    if(obj?.name)return obj.name;
    const raw=String(profile?.premium_title||profile?.main_title_name||'');
    if(!raw)return '';
    // premium_title antigo pode guardar o ID do item da loja. Resolva para o nome real.
    const item=premiumItemById(raw);
    if(item?.kind==='title')return item.name||'';
    // Nunca exiba IDs internos como custom-xxxx no perfil.
    if(/^custom-/i.test(raw)||/^[0-9a-f]{8}-[0-9a-f-]{27,}$/i.test(raw))return '';
    return raw;
  }
  function registerTitleFont(item){const url=item?.title_font_url||item?.title_font_asset_url;if(!url||!item?.id)return;const family=`Q-RivalCustom_${String(item.id).replace(/[^a-zA-Z0-9_-]/g,'_')}`;if(url.includes('fonts.googleapis.com')||url.includes('fonts.gstatic.com')){const key='quizup-font-link-'+family;if(!document.getElementById(key)){const l=document.createElement('link');l.id=key;l.rel='stylesheet';l.href=url;document.head.appendChild(l)}}else{const key='quizup-font-style-'+family;if(!document.getElementById(key)){const st=document.createElement('style');st.id=key;st.textContent=`@font-face{font-family:'${family}';src:url('${url}');font-display:swap}`;document.head.appendChild(st)}}return family}
  function titleFontFamily(t){const f=registerTitleFont(t);return f?`'${f}'`:`'${String(t?.title_font||'Inter').replace(/'/g,'')}'`}
  function titleVisualMarkup(t, cls='premium-title-visual'){if(!t)return '';const effect=t.effect_style||'none';if(t.asset_url)return `<span class="title-visual-shell title-effect-${esc(effect)}"><img class="${cls}" src="${esc(t.asset_url)}" alt="${esc(t.name||'Título')}" loading="lazy"></span>`;return `<span class="${cls} title-effect-${esc(effect)}" style="--title-color:${esc(t.title_color||'#ffd21a')};--title-font:${esc(titleFontFamily(t))}">${t.icon?`${esc(t.icon)} `:''}${esc(t.name||'')}</span>`}
  async function loadUserTitles(userId=S.user?.id){if(!sb||!userId)return [];const {data,error}=await sb.from('user_titles').select('id,user_id,title_id,is_main,acquired_at,titles(id,name,description,icon,asset_url,asset_type,effect_style,title_color,title_font,title_font_url,title_font_asset_url,active)').eq('user_id',userId).order('acquired_at',{ascending:true});if(error){console.warn('user titles',error.message);return [];}const rows=(data||[]).map(x=>({...x,name:x.titles?.name||'',description:x.titles?.description||'',icon:x.titles?.icon||'🏷️',asset_url:x.titles?.asset_url||'',asset_type:x.titles?.asset_type||'',effect_style:x.titles?.effect_style||'none',title_color:x.titles?.title_color||'#ffd21a',title_font:x.titles?.title_font||'Inter',title_font_url:x.titles?.title_font_url||'',title_font_asset_url:x.titles?.title_font_asset_url||''}));rows.forEach(registerTitleFont);if(userId===S.user?.id)S.userTitles=rows;return rows;}
  async function setMainTitle(titleId){if(!sb||!S.user)return;const {error}=await sb.rpc('set_main_title',{p_title_id:titleId||null});if(error)return alert(error.message);await loadUserTitles(S.user.id);S.profile={...S.profile,main_title_id:titleId||null};S.profileDetails=null;render();}
  const OFFICIAL_STATIC_FRAMES=new Set(['frame-fire','frame-water','frame-earth','frame-air','frame-darkness','frame-light']);
  function activeCosmeticsFor(profile=S.profile){
    const isOther=!!(profile?.id&&S.user?.id&&profile.id!==S.user.id);
    const a=isOther?{}:premiumActive();
    const requestedFrame=profile?.premium_frame || a.frame || '';
    const frameItem=premiumItemById(requestedFrame);
    const safeFrame=(frameItem?.kind==='frame' && frameItem?.asset_type==='image/png' && String(frameItem?.effect_style||'none')==='none')?String(frameItem.id):'';
    return {
      frame: safeFrame,
      effect: profile?.premium_effect || a.effect || '',
      theme: profile?.premium_theme || a.theme || '',
      background: profile?.premium_background || a.background || '',
      avatar: profile?.premium_avatar || a.avatar || '',
      title: profile?.role==='admin' ? (profile?.premium_title || a.title || '') : (getMainTitle(profile) || profile?.premium_title || a.title || ''),
      badge: profile?.premium_badge || a.badge || ''
    };
  }
  function cosmeticsMarkup(profile, avatarClass='avatar mini', extra=''){
    const c=activeCosmeticsFor(profile);
    const frame=c.frame?` premium-frame ${esc(c.frame)}`:'';
    const vip=isVip(profile)?'<em class="premium-badge">VIP</em>':'';
    const glow=(isVip(profile)||c.title||c.frame||c.theme)?' premium-name-glow':'';
    return {avatarClass:`${avatarClass}${frame} ${extra}`, title:c.title||'', vip, glow};
  }
  // O catálogo da Loja é 100% controlado pelo banco/painel do administrador.
  // Não existem mais itens fictícios/hardcoded na Loja.
  function money(v){return `${Number(v||0).toLocaleString('pt-BR')} ⚡`}
  function itemPurchaseEnabled(item){if(!S.storeSettings?.enabled)return false;return storeCategoryEnabled(item?.cat||'')}
  function storeCategoryEnabled(cat){if(!S.storeSettings?.enabled)return false;if(cat==='VIP')return !!S.storeSettings.vip_enabled;if(cat==='Moedas')return !!S.storeSettings.coins_enabled&&!!S.storeSettings.payments_enabled;if(cat==='Passe')return !!S.storeSettings.pass_enabled;return !!S.storeSettings.cosmetics_enabled}
  async function loadCoinPackages(){
    if(!sb)return;
    const {data,error}=await sb.from('coin_packages').select('id,name,coins,price_cents,active,sort_order').eq('active',true).order('sort_order').order('coins');
    if(!error)S.coinPackages=data||[];
  }
  async function loadAdminCoinPackages(){
    if(!sb||!S.isAdmin)return;
    const {data,error}=await sb.from('coin_packages').select('id,name,coins,price_cents,active,sort_order').order('sort_order').order('coins');
    if(!error)S.adminCoinPackages=data||[];
  }
  async function createCoinPackage(){
    if(!sb||!S.isAdmin)return;
    const name=$('#coinPackName')?.value.trim();
    const coins=Number($('#coinPackCoins')?.value||0);
    const price=Number(String($('#coinPackPrice')?.value||0).replace(',','.'));
    if(!name||coins<=0||price<=0)return alert('Informe nome, quantidade de Coins e preço maior que zero.');
    const {error}=await sb.from('coin_packages').insert({name,coins,price_cents:Math.round(price*100),active:true,sort_order:Number($('#coinPackOrder')?.value||0),created_by:S.user.id});
    if(error)alert(error.message);else{$('#coinPackageForm')?.reset();await loadAdminCoinPackages();await loadCoinPackages();render()}
  }
  async function editCoinPackage(id){
    if(!sb||!S.isAdmin)return;const x=(S.adminCoinPackages||[]).find(i=>i.id===id);if(!x)return;
    const name=prompt('Nome do pacote:',x.name);if(name===null)return;
    const coins=prompt('Quantidade de QuizCoins:',String(x.coins));if(coins===null)return;
    const price=prompt('Preço em reais (ex.: 10.00):',String((Number(x.price_cents||0)/100).toFixed(2)));if(price===null)return;
    const active=confirm('Deixar este pacote ativo?');
    const {error}=await sb.from('coin_packages').update({name:name.trim(),coins:Number(coins),price_cents:Math.round(Number(String(price).replace(',','.'))*100),active}).eq('id',id);
    if(error)alert(error.message);else{await loadAdminCoinPackages();await loadCoinPackages();render()}
  }
  async function createCoinPayment(packageId){return openManualCoinPurchase(packageId)}
  async function openManualCoinPurchase(packageId){
    if(!sb||!S.user)return alert('Faça login para comprar QuizCoins.');
    const {data,error}=await sb.rpc('create_manual_coin_order',{p_coin_package_id:packageId});
    if(error)return alert(error.message||'Não foi possível criar a solicitação de compra.');
    S.manualCoinOrder={id:data.id,coins:data.coins,amount_cents:data.amount_cents,status:data.status};
    await loadManualCoinChat(data.id);
    render();
  }
  async function loadManualCoinChat(orderId){
    if(!sb||!S.user||!orderId)return;
    const {data:o}=await sb.from('manual_coin_orders').select('id,coins,amount_cents,status,payment_link,proof_path,created_at,updated_at,rejection_reason').eq('id',orderId).maybeSingle();
    if(o)S.manualCoinOrder=o;
    const {data,error}=await sb.from('manual_coin_messages').select('id,order_id,sender_id,message,message_type,media_path,created_at').eq('order_id',orderId).order('created_at',{ascending:true});
    if(!error)S.manualCoinMessages=data||[];
    if(S.manualCoinRealtime)sb.removeChannel(S.manualCoinRealtime);
    S.manualCoinRealtime=sb.channel('manual-coin-'+orderId).on('postgres_changes',{event:'INSERT',schema:'public',table:'manual_coin_messages',filter:`order_id=eq.${orderId}`},payload=>{if(!S.manualCoinMessages.some(x=>x.id===payload.new.id)){S.manualCoinMessages.push(payload.new);if(S.route==='store')render()}}).subscribe();
  }
  async function sendManualCoinMessage(){
    const input=$('#manualCoinInput');const msg=input?.value.trim();if(!msg||!S.manualCoinOrder?.id)return;
    const {error}=await sb.from('manual_coin_messages').insert({order_id:S.manualCoinOrder.id,sender_id:S.user.id,message:msg,message_type:'text'});
    if(error)return alert(error.message);input.value='';await loadManualCoinChat(S.manualCoinOrder.id);render();
  }
  async function uploadManualCoinProof(file){
    if(!file||!S.manualCoinOrder?.id)return;
    if(file.size>8*1024*1024)return alert('O comprovante deve ter no máximo 8 MB.');
    if(!['image/png','image/jpeg','image/webp','application/pdf'].includes(file.type))return alert('Envie PNG, JPG, WebP ou PDF.');
    const path=`${S.user.id}/${S.manualCoinOrder.id}/${Date.now()}-${Math.random().toString(36).slice(2,8)}.${(file.name.split('.').pop()||'jpg').toLowerCase()}`;
    const {error:up}=await sb.storage.from('purchase-proofs').upload(path,file,{cacheControl:'3600',upsert:false,contentType:file.type});
    if(up)return alert(up.message||'Não foi possível enviar o comprovante.');
    const {error}=await sb.rpc('submit_manual_coin_proof',{p_order_id:S.manualCoinOrder.id,p_proof_path:path});
    if(error)return alert(error.message||'Não foi possível registrar o comprovante.');
    await loadManualCoinChat(S.manualCoinOrder.id);render();
  }
