  function detailChart(){const ids=[S.user.id,...((S.match?.player_ids||[]).filter(x=>x!==S.user.id).slice(0,1))];const pts=ids.map(id=>{let total=0;return Array.from({length:7},(_,i)=>{const a=S.match?.answers?.[`${id}:${i}`];total+=Number(a?.score||0);return total})});const max=140;const make=(arr)=>arr.map((v,i)=>`${20+i*50},${150-(v/max*120)}`).join(' ');return `<svg class="score-chart" viewBox="0 0 340 175" role="img"><line x1="20" y1="150" x2="320" y2="150"/><line x1="20" y1="30" x2="20" y2="150"/><polyline points="${make(pts[0]||[])}"/><polyline class="rival-line" points="${make(pts[1]||[])}"/><text x="20" y="168">1</text><text x="70" y="168">2</text><text x="120" y="168">3</text><text x="170" y="168">4</text><text x="220" y="168">5</text><text x="270" y="168">6</text><text x="315" y="168">7</text></svg>`}


