  async function loadRanking(){if(!sb)return;let rows=[];if(S.rankCategory&&S.rankCategory!=='__global__'){const {data,error}=await sb.rpc('get_topic_ranking',{p_category:S.rankCategory,p_limit:100});if(error)return alert(error.message);rows=data||[]}else{const {data,error}=await sb.from('profiles').select('id,username,display_name,avatar_url,xp,wins,losses,draws,level,main_title_id,premium_vip,premium_vip_until,premium_frame,premium_effect,premium_theme,premium_avatar,premium_title,premium_badge').order('xp',{ascending:false}).limit(100);if(error)return alert(error.message);rows=data||[]}const ids=rows.map(x=>x.id).filter(Boolean);if(ids.length){const {data:ts}=await sb.from('user_titles').select('id,user_id,title_id,is_main,acquired_at,titles(id,name,description,icon,asset_url,asset_type,effect_style,title_color,title_font,title_font_url,title_font_asset_url)').in('user_id',ids).order('acquired_at',{ascending:true});const grouped={};(ts||[]).forEach(x=>{(grouped[x.user_id]||(grouped[x.user_id]=[])).push({...x,name:x.titles?.name||'',description:x.titles?.description||'',icon:x.titles?.icon||'🏷️',asset_url:x.titles?.asset_url||'',asset_type:x.titles?.asset_type||'',effect_style:x.titles?.effect_style||'none',title_color:x.titles?.title_color||'#ffd21a',title_font:x.titles?.title_font||'Inter',title_font_url:x.titles?.title_font_url||'',title_font_asset_url:x.titles?.title_font_asset_url||''})});rows=rows.map(r=>{const own=grouped[r.id]||[];return {...r,owned_titles:own,main_title:own.find(t=>t.is_main)||null}})}S.rankRows=rows;render()}

