    const pendingQHtml=pendingQs.length?pendingQs.map(q=>`<div class="question-admin"><span class="badge">${esc(q.category_name)}</span><span class="badge">PENDENTE</span><p><b>${esc(q.question_text)}</b></p><div class="admin-actions"><button class="secondary approveQuestion" data-id="${q.id}">✓ APROVAR</button><button class="danger rejectQuestion" data-id="${q.id}">✕ EXCLUIR</button></div></div>`).join(''):'<div class="muted">Nenhuma pergunta pendente.</div>';
    const questionHtml=filtered.map(q=>`<div class="question-admin ${q.active?'':'inactive'}"><div><span class="badge">${esc(q.category_name)}</span><span class="badge ${q.active?'ok':'off'}">${q.active?'ATIVA':'INATIVA'}</span>${q.approval_status&&q.approval_status!=='approved'?'<span class="badge">PENDENTE</span>':''}<p><b>${esc(q.question_text)}</b></p><div class="muted">${(q.options||[]).map((o,i)=>`${'ABCD'[i]}) ${esc(o)}${i===q.correct_index?' ✓':''}`).join(' • ')}</div></div><div class="admin-actions"><button class="secondary editQuestion" data-id="${q.id}">✏️ EDITAR</button><button class="secondary toggleQuestion" data-id="${q.id}" data-active="${q.active}">${q.active?'⏸ INATIVAR':'▶ ATIVAR'}</button><button class="danger deleteQuestion" data-id="${q.id}">🗑 EXCLUIR</button></div></div>`).join('');
