  async function createShopRotation(){if(!sb||!S.isAdmin)return;const item=$('#rotItem')?.value;if(!item)return alert('Escolha um item.');const payload={item_id:item,starts_at:new Date($('#rotStart')?.value).toISOString(),ends_at:new Date($('#rotEnd')?.value).toISOString(),active:$('#rotActive')?.checked!==false,sort_order:Number($('#rotOrder')?.value||0),created_by:S.user.id};const {error}=await sb.from('qr_shop_rotation').insert(payload);if(error)return alert(error.message);await loadAdminModeData();render()}
  async function createSeasonReward(){if(!sb||!S.isAdmin)return;const season=$('#seasonId')?.value;if(!season)return alert('Crie/seleciona uma temporada primeiro.');const payload={season_id:season,level:Number($('#seasonLevel')?.value||1),reward_type:$('#seasonRewardType')?.value||'coins',reward_coins:Number($('#seasonCoins')?.value||0),reward_item_id:$('#seasonItem')?.value||null,premium_only:$('#seasonPremium')?.checked===true};const {error}=await sb.from('qr_season_rewards').upsert(payload,{onConflict:'season_id,level'});if(error)return alert(error.message);await loadAdminModeData();render()}
