  function getImageDimensions(file){return new Promise((resolve,reject)=>{const img=new Image();const url=URL.createObjectURL(file);img.onload=()=>{URL.revokeObjectURL(url);resolve({width:img.naturalWidth,height:img.naturalHeight})};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('Não foi possível ler a imagem.'))};img.src=url;});}
  async function uploadAdminAsset(file, folder, maxMB=8){if(!sb||!S.isAdmin||!file)return {url:null,type:null};if(!file.type.startsWith('image/'))throw new Error('Escolha uma imagem válida.');if(file.size>maxMB*1024*1024)throw new Error(`O arquivo deve ter no máximo ${maxMB} MB.`);const ext=(file.name.split('.').pop()||'png').toLowerCase().replace(/[^a-z0-9]/g,'')||'png';const path=`${folder}/${S.user.id}/${Date.now()}-${Math.random().toString(36).slice(2,9)}.${ext}`;const {error}=await sb.storage.from('admin-assets').upload(path,file,{cacheControl:'31536000',upsert:false,contentType:file.type});if(error)throw new Error(`Falha ao enviar o arquivo: ${error.message}`);return {url:sb.storage.from('admin-assets').getPublicUrl(path).data.publicUrl,type:file.type};}
  function adminAssetPreview(url,name,cls='admin-asset-thumb'){return url?`<img class="${cls}" src="${esc(url)}" alt="${esc(name||'Arquivo')}" loading="lazy">`:''}
  async function loadAdminBadges(){if(!sb||!S.isAdmin)return;const {data,error}=await sb.from('badges').select('id,name,description,icon,asset_url,asset_type,active,created_at').order('created_at',{ascending:false});if(!error)S.adminBadges=data||[];}
  async function createBadge(){if(!sb||!S.isAdmin)return;const name=$('#badgeName')?.value.trim();const desc=$('#badgeDesc')?.value.trim()||null;const file=$('#badgeFile')?.files?.[0]||null;const sell=!!$('#badgeSell')?.checked;const price=Number($('#badgePrice')?.value||0);const promo=Number($('#badgePromoPrice')?.value||0);if(!name)return alert('Informe o nome do emblema.');if(!file)return alert('Escolha a imagem do emblema.');if(price<0|| (sell&&price<=0))return alert('Informe um preço válido para o emblema.');try{if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type))return alert('Emblemas aceitam PNG, JPG/JPEG, WebP ou GIF.');if(file.size>5*1024*1024)return alert('O emblema deve ter no máximo 5 MB.');const dims=await getImageDimensions(file);if(dims.width!==128||dims.height!==128)return alert('O emblema deve ter exatamente 128 × 128 px.');const asset=await uploadAdminAsset(file,'badges',5);let badge=null;const {data:existing}=await sb.from('badges').select('id').eq('name',name).maybeSingle();if(existing?.id){const {data,error}=await sb.from('badges').update({description:desc,icon:'🏅',asset_url:asset.url,asset_type:asset.type,active:true,created_by:S.user.id}).eq('id',existing.id).select('id').single();if(error)throw error;badge=data}else{const {data,error}=await sb.from('badges').insert({name,description:desc,icon:'🏅',asset_url:asset.url,asset_type:asset.type,active:true,created_by:S.user.id}).select('id').single();if(error)throw error;badge=data}const id=`badge-${badge.id}`;const {data:oldSale}=await sb.from('premium_items').select('id').eq('source_type','badge').eq('source_id',badge.id).maybeSingle();const payload={name,category:'Emblemas',description:desc,price_cents:price,price_coins:price,promo_price_cents:promo>0?promo:null,promo_price_coins:promo>0?promo:null,promo_active:promo>0&&promo<price,promo_expires_at:null,icon:'🏅',effect_style:'none',asset_url:asset.url,asset_type:asset.type,kind:'badge',source_type:'badge',source_id:badge.id,active:sell,created_by:S.user.id};if(oldSale?.id){const {error:pe}=await sb.from('premium_items').update(payload).eq('id',oldSale.id);if(pe)throw pe}else{const {error:pe}=await sb.from('premium_items').insert({id,...payload});if(pe)throw pe}alert(existing?.id?'✅ Emblema atualizado e sincronizado com a Loja.':'✅ Emblema criado'+(sell?' e colocado à venda na Loja.':'.'));$('#badgeForm')?.reset();await loadAdminBadges();await loadAdminPremiumItems();await loadPremiumItems();render()}catch(e){alert(e?.message||'Não foi possível criar o emblema.')}}
  async function editBadge(id){openAdminCosmeticEditor(id)}
  async function deleteBadge(id){if(!sb||!S.isAdmin)return;if(!confirm('Excluir este emblema? Ele também será retirado dos inventários e perfis que o usam.'))return;const {error}=await sb.rpc('admin_delete_badge',{p_badge_id:id});if(error)return alert(error.message);await loadAdminBadges();await loadAdminPremiumItems();await loadPremiumItems();S.inventoryItems=[];render();}
  async function loadAdminTitles(){if(!sb||!S.isAdmin)return;const {data,error}=await sb.from('titles').select('id,name,description,icon,asset_url,asset_type,effect_style,title_color,title_font,title_font_url,title_font_asset_url,asset_width,asset_height,active,created_at').order('created_at',{ascending:false});if(!error)S.adminTitles=data||[];}
  async function createTitle(){if(!sb||!S.isAdmin)return;const name=$('#titleName')?.value.trim();const desc=$('#titleDesc')?.value.trim()||null;const effect_style=$('#titleEffect')?.value||'none';const sell=!!$('#titleSell')?.checked;const price=Number($('#titlePrice')?.value||0);const promo=Number($('#titlePromoPrice')?.value||0);const file=$('#titleFile')?.files?.[0]||null;if(!name)return alert('Informe o nome do título.');if(!file)return alert('Escolha o PNG do título.');if(file.type!=='image/png')return alert('O título deve ser obrigatoriamente PNG.');if(file.size>5*1024*1024)return alert('O PNG deve ter no máximo 5 MB.');if(sell&&price<=0)return alert('Informe o preço do título.');try{const d=await getImageDimensions(file);if(d.width!==600||d.height!==160)return alert('O PNG do título deve ter exatamente 600 × 160 px.');const asset=await uploadAdminAsset(file,'titles');const {data:title,error}=await sb.from('titles').insert({name,icon:'',description:desc,effect_style,asset_url:asset.url,asset_type:asset.type,active:true,created_by:S.user.id,title_color:'#ffd21a',title_font:'Inter',asset_width:600,asset_height:160}).select('id').single();if(error)throw error;const id=`title-${title.id}`;const {error:pe}=await sb.from('premium_items').insert({id,name,category:'Títulos',description:desc,price_cents:price,price_coins:price,promo_price_cents:promo>0?promo:null,promo_price_coins:promo>0?promo:null,promo_active:promo>0&&promo<price,promo_expires_at:null,icon:'',effect_style,asset_url:asset.url,asset_type:asset.type,kind:'title',source_type:'title',source_id:title.id,active:sell,created_by:S.user.id,title_color:'#ffd21a',title_font:'Inter',asset_width:600,asset_height:160});if(pe)throw pe;alert('✅ Título criado'+(sell?' e colocado à venda na Loja.':'.'));$('#titleForm')?.reset();await loadAdminTitles();await loadAdminPremiumItems();await loadPremiumItems();render()}catch(e){alert(e?.message||'Não foi possível criar o título.')}}
  function cosmeticSpec(kind){
    return ({
      avatar:{label:'Avatar',w:256,h:256,accept:'image/png,image/jpeg,image/webp',max:5,folder:'avatars'},
      frame:{label:'Moldura',w:256,h:256,accept:'image/png,image/svg+xml',max:5,folder:'frames'},
      background:{label:'Fundo de perfil',w:800,h:500,accept:'image/png,image/jpeg,image/webp,image/gif',max:8,folder:'backgrounds'},
      title:{label:'Título',w:600,h:160,accept:'image/png',max:5,folder:'titles'},
      emoji:{label:'Emoji',w:128,h:128,accept:'image/png,image/webp,image/gif',max:3,folder:'emojis'},
      badge:{label:'Moldura/Emblema legado',w:128,h:128,accept:'image/png,image/jpeg,image/webp,image/gif',max:5,folder:'badges'}
    })[kind]||{label:'Item',w:null,h:null,accept:'image/png,image/jpeg,image/webp,image/gif,image/svg+xml',max:5,folder:'premium'};
  }
  function closeCosmeticEditor(){document.getElementById('quizupCosmeticEditor')?.remove();}
  function openAdminCosmeticEditor(id){
    if(!sb||!S.isAdmin)return;
    const item=(S.adminPremiumItems||[]).find(i=>String(i.id)===String(id));
    if(!item)return alert('Item não encontrado.');
    closeCosmeticEditor();
    const kind=item.kind||'theme', spec=cosmeticSpec(kind);
    const title=(kind==='title'&&item.source_id)?(S.adminTitles||[]).find(t=>String(t.id)===String(item.source_id)):null;
    const badge=(kind==='badge'&&item.source_id)?(S.adminBadges||[]).find(b=>String(b.id)===String(item.source_id)):null;
    const source=title||badge||item;
    const active=!!item.active;
    const currentPrice=Number(item.price_coins??item.price_cents??0);
    const currentPromo=Number(item.promo_price_coins??item.promo_price_cents??0);
    const overlay=document.createElement('div');
    overlay.id='quizupCosmeticEditor';
    overlay.className='cosmetic-editor-backdrop';
    overlay.innerHTML=`<div class="cosmetic-editor-card" role="dialog" aria-modal="true">
      <div class="cosmetic-editor-head"><div><span>✦ EDITAR ${esc(spec.label).toUpperCase()}</span><h2>${esc(item.name||source.name||'Item')}</h2></div><button type="button" class="cosmetic-editor-close" id="cosmeticEditorClose">×</button></div>
      <form id="cosmeticEditorForm" class="form">
        <div class="cosmetic-editor-preview">${item.asset_url?`<img src="${esc(item.asset_url)}" alt="Prévia">`:'<span>Sem imagem</span>'}</div>
        <div class="cosmetic-editor-grid"><label>Nome do item<input id="ceName" required maxlength="80" value="${esc(source.name||item.name||'')}"></label><label>Ícone/emoji<input id="ceIcon" maxlength="12" value="${esc(source.icon||item.icon||'')}"></label></div>
        <label>Descrição<textarea id="ceDesc" maxlength="300">${esc(source.description||item.description||'')}</textarea></label>
        <div class="cosmetic-editor-grid"><label>Preço normal (QuizCoins)<input id="cePrice" type="number" min="0" step="1" value="${currentPrice}"></label><label>Preço promocional<input id="cePromo" type="number" min="0" step="1" value="${currentPromo||''}" placeholder="Vazio = sem promoção"></label></div>
        <label>Fim da promoção (opcional)<input id="ceExpires" type="datetime-local" value="${item.promo_expires_at?new Date(item.promo_expires_at).toISOString().slice(0,16):''}"></label>
        ${kind==='title'?`<label>Efeito visual<select id="ceEffect"><option value="none">Sem efeito</option><option value="fire">🔥 Fogo</option><option value="water">💧 Água</option><option value="earth">🌍 Terra</option><option value="air">🌪️ Ar</option><option value="lightning">⚡ Raio</option><option value="darkness">🌑 Trevas</option><option value="light">✨ Luz</option><option value="gold">🥇 Dourado</option><option value="silver">🥈 Prata</option><option value="bronze">🥉 Bronze</option><option value="vip">👑 VIP</option><option value="diamond">💎 Diamante</option><option value="ruby">♦️ Rubi</option><option value="emerald">💚 Esmeralda</option></select></label>`:''}
        ${kind==='title'?`<div class="cosmetic-editor-grid"><label>Cor do título<input id="ceColor" type="text" maxlength="7" value="${esc(item.title_color||title?.title_color||'#ffd21a')}"></label><label>Fonte<input id="ceFont" maxlength="60" value="${esc(item.title_font||title?.title_font||'Inter')}"></label></div>`:''}
        ${kind==='background'?`<label>Tipo do fundo<select id="ceBgType"><option value="static" ${item.asset_type==='static'?'selected':''}>🖼️ Estático</option><option value="animated" ${item.asset_type==='animated'?'selected':''}>🎞️ Animado (GIF)</option></select></label>`:''}
        <div class="cosmetic-upload-box"><b>🖼️ Trocar imagem</b><span>${spec.w&&spec.h?`Obrigatório: ${spec.w} × ${spec.h} px`:'Resolução definida pelo tipo'}</span><input id="ceFile" type="file" accept="${spec.accept}"><small id="ceFileName">Nenhum arquivo novo selecionado</small></div>
        <label class="check-row"><input id="ceActive" type="checkbox" ${active?'checked':''}> Disponível para venda na Loja</label>
        <div class="cosmetic-editor-spec">📐 <b>${esc(spec.label)}:</b> ${spec.w&&spec.h?`${spec.w} × ${spec.h} px`: 'padrão do tipo'} • máximo ${spec.max} MB.${kind==='avatar'?' O conteúdo principal deve ficar centralizado dentro da área circular segura.':''}</div>
        <div class="cosmetic-editor-actions"><button type="button" class="secondary" id="cosmeticEditorCancel">CANCELAR</button><button type="submit" class="primary">SALVAR TODAS AS ALTERAÇÕES</button></div>
      </form></div>`;
    document.body.appendChild(overlay);
    if(kind==='title'){
      const el=overlay.querySelector('#ceEffect'); if(el)el.value=item.effect_style||source.effect_style||'none';
    }
    overlay.querySelector('#cosmeticEditorClose').onclick=closeCosmeticEditor;
    overlay.querySelector('#cosmeticEditorCancel').onclick=closeCosmeticEditor;
    overlay.addEventListener('click',e=>{if(e.target===overlay)closeCosmeticEditor()});
    overlay.querySelector('#ceFile').addEventListener('change',e=>{overlay.querySelector('#ceFileName').textContent=e.target.files?.[0]?e.target.files[0].name:'Nenhum arquivo novo selecionado'});
    overlay.querySelector('#cosmeticEditorForm').onsubmit=async e=>{
      e.preventDefault();
      const name=overlay.querySelector('#ceName').value.trim();
      const desc=overlay.querySelector('#ceDesc').value.trim()||null;
      const icon=overlay.querySelector('#ceIcon').value.trim();
      const price=Number(overlay.querySelector('#cePrice').value||0);
      const promo=Number(overlay.querySelector('#cePromo').value||0);
      const expires=overlay.querySelector('#ceExpires').value;
      const newFile=overlay.querySelector('#ceFile').files?.[0]||null;
      if(!name)return alert('Informe o nome do item.');
      if(!Number.isFinite(price)||price<0)return alert('Preço inválido.');
      if(promo>0&&(promo>=price||price<=0))return alert('O preço promocional precisa ser menor que o preço normal.');
      if(newFile){
        if(newFile.size>spec.max*1024*1024)return alert(`A imagem deve ter no máximo ${spec.max} MB.`);
        if(!spec.accept.split(',').includes(newFile.type))return alert('Formato de imagem inválido para este item.');
        if(spec.w&&spec.h){const d=await getImageDimensions(newFile);if(d.width!==spec.w||d.height!==spec.h)return alert(`A imagem deve ter exatamente ${spec.w} × ${spec.h} px.`);}
      }
      let asset_url=item.asset_url||null,asset_type=item.asset_type||null,asset_width=item.asset_width||spec.w||null,asset_height=item.asset_height||spec.h||null;
      try{
        if(newFile){const folder=spec.folder;const asset=await uploadAdminAsset(newFile,folder,spec.max);asset_url=asset.url;asset_type=asset.type;asset_width=spec.w||asset_width;asset_height=spec.h||asset_height;}
        const effect=kind==='frame'?'none':(overlay.querySelector('#ceEffect')?.value||item.effect_style||'none');
        const bgType=overlay.querySelector('#ceBgType')?.value||item.asset_type||'static';
        if(kind==='background'&&newFile&&bgType==='animated'&&newFile.type!=='image/gif')return alert('Fundo animado deve ser GIF.');
        if(kind==='background'&&newFile&&bgType==='static'&&!['image/png','image/jpeg','image/webp'].includes(newFile.type))return alert('Fundo estático deve ser PNG, JPG/JPEG ou WebP.');
        const titleColor=overlay.querySelector('#ceColor')?.value.trim()||item.title_color||'#ffd21a';
        const titleFont=overlay.querySelector('#ceFont')?.value.trim()||item.title_font||'Inter';
        if(kind==='title'&&!/^#[0-9a-fA-F]{6}$/.test(titleColor))return alert('Cor do título inválida. Use #RRGGBB.');
        const payload={name,description:desc,icon,price_coins:price,price_cents:price,promo_price_coins:promo>0?promo:null,promo_price_cents:promo>0?promo:null,promo_active:promo>0&&promo<price,promo_expires_at:expires?new Date(expires).toISOString():null,active:!!overlay.querySelector('#ceActive').checked,asset_url,asset_type:kind==='background'?bgType:asset_type,asset_width:asset_width,asset_height:asset_height,effect_style:effect};
        if(kind==='title'){payload.title_color=titleColor;payload.title_font=titleFont;}
        const {error}=await sb.from('premium_items').update(payload).eq('id',item.id);if(error)throw error;
        if(kind==='title'&&item.source_id){const {error:te}=await sb.from('titles').update({name,description:desc,icon,effect_style:effect,title_color:titleColor,title_font:titleFont,asset_url,asset_type:asset_type||'image/png',asset_width:600,asset_height:160}).eq('id',item.source_id);if(te)throw te;}
        if(kind==='badge'&&item.source_id){const {error:be}=await sb.from('badges').update({name,description:desc,icon:icon||'🏅',asset_url,asset_type,active:true}).eq('id',item.source_id);if(be)throw be;}
        closeCosmeticEditor();
        await loadAdminTitles();await loadAdminBadges();await loadAdminPremiumItems();await loadPremiumItems();render();
        alert('✅ Todas as alterações foram salvas.');
      }catch(err){alert(err?.message||'Não foi possível salvar as alterações.')}
    };
  }
  async function editTitle(id){
    const premium=(S.adminPremiumItems||[]).find(x=>String(x.id)===String(id)|| (x.kind==='title'&&String(x.source_id)===String(id)));
    if(!premium)return alert('Item de título não encontrado.');
    openAdminCosmeticEditor(premium.id);
  }
