      const kind={Molduras:'frame',Efeitos:'effect',Títulos:'title',Emojis:'emoji',Avatares:'avatar','Fundos de Perfil':'background',Temas:'theme',Badges:'badge',Emblemas:'frame'}[category]||'theme';
      const frameWidth=kind==='frame'?256:null, frameHeight=kind==='frame'?256:null;
      const id=`custom-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;const {error}=await sb.from('premium_items').insert({id,name,category,description,rarity:$('#premiumItemRarity')?.value||'common',price_cents:price,price_coins:price,promo_price_cents:promoPrice>0?promoPrice:null,promo_price_coins:promoPrice>0?promoPrice:null,promo_active:promoPrice>0&&promoPrice<price,promo_expires_at:$('#premiumItemPromoExpires')?.value?new Date($('#premiumItemPromoExpires').value).toISOString():null,icon,effect_style,asset_url,asset_type:kind==='background'?($('#premiumItemBackgroundType')?.value||'static'):file?.type||null,kind,asset_width:frameWidth,asset_height:frameHeight,frame_inset_percent:kind==='frame'?0:null,frame_version:kind==='frame'?'v1':null,active:true,created_by:S.user.id,source_type:kind==='title'?'title':kind==='badge'?'badge':kind==='background'?'background':null,source_id:null});if(error)throw error;
