  async function loadPremiumInventory(){
    if(!sb||!S.user)return;
    const {data,error}=await sb.from('user_premium_items').select('item_id,active,purchased_at,expires_at').eq('user_id',S.user.id);
    if(error){console.warn('premium inventory',error.message);return;}
    const ids=(data||[]).map(x=>x.item_id).filter(Boolean);
    let items=[];
    if(ids.length){const {data:rows}=await sb.from('premium_items').select('id,name,category,description,price_coins,price_cents,promo_price_coins,promo_price_cents,promo_active,promo_expires_at,icon,asset_url,asset_type,effect_style,kind,source_type,source_id,active').in('id',ids);items=rows||[];}
    S.inventoryItems=(data||[]).map(row=>{const x=items.find(i=>i.id===row.item_id);if(!x)return null;return {...x,price:Number(x.price_coins??x.price_cents??0),asset_type:x.asset_type||'',effect_style:x.effect_style||'none',title_color:x.title_color||'#ffd21a',title_font:x.title_font||'Inter',title_font_url:x.title_font_url||'',title_font_asset_url:x.title_font_asset_url||'',source_type:x.source_type||'',source_id:x.source_id||'',rarity:x.rarity||'common',promo_price:Number(x.promo_price_coins??x.promo_price_cents??0),cat:x.category,desc:x.description||'',activeOwned:(!!row.active && (!row.expires_at || new Date(row.expires_at).getTime()>Date.now())) || (x.kind==='title' && S.profile?.role==='admin' && String(S.profile?.premium_title||'')===String(row.item_id)),kind:x.kind||({Molduras:'frame',Efeitos:'effect',Títulos:'title',Emojis:'emoji',Avatares:'avatar','Fundos de Perfil':'background',Temas:'theme',Badges:'badge',Emblemas:'frame'}[x.category]||'theme'),purchased_at:row.purchased_at||null,expires_at:row.expires_at||null};}).filter(Boolean);
    S.premium.owned=[...new Set([...(S.premium.owned||[]),...S.inventoryItems.filter(x=>!x.expires_at||new Date(x.expires_at).getTime()>Date.now()).map(x=>x.id)])];
    const activeByKind={};S.inventoryItems.filter(x=>x.activeOwned).forEach(x=>{if(x.kind)activeByKind[x.kind]=x.id});
    S.premium.active={...activeByKind,...S.premium.active};
  }
  async function useInventoryItem(id){
    const item=S.inventoryItems.find(x=>x.id===id);if(!item||!sb)return;
    if(item.activeOwned){
      const {error}=await sb.from('user_premium_items').update({active:false}).eq('user_id',S.user.id).eq('item_id',id);
      if(error)return alert(error.message||'Não foi possível desativar o item.');
      const next={...(S.premium.active||{})};delete next[item.kind];S.premium.active=next;
    }else{
      const {error}=await sb.rpc('activate_premium_item',{p_item_id:id});
      if(error)return alert(error.message||'Não foi possível ativar o item.');
      S.premium.active={...S.premium.active,[item.kind]:item.id};
      if(item.kind==='title')await loadUserTitles(S.user.id);
      if(item.kind==='vip')S.premium.owned=[...new Set([...(S.premium.owned||[]),'vip'])];
    }
    premiumSave();await persistPremiumProfile();await loadPremiumInventory();render();
  }
  async function loadProfile(){
    if(!sb||!S.user)return;
    let {data,error}=await sb.from('profiles').select('id,username,display_name,avatar_url,xp,level,wins,losses,streak,role,coins,main_title_id,premium_vip,premium_vip_until,premium_frame,premium_effect,premium_theme,premium_background,premium_avatar,premium_title,premium_badge,premium_pass_until').eq('id',S.user.id).single();
    if(error){const fallback=await sb.from('profiles').select('id,username,display_name,avatar_url,xp,level,wins,losses,streak,role').eq('id',S.user.id).single();data=fallback.data;error=fallback.error;}
    S.profile=data||{username:S.user.email?.split('@')[0],display_name:S.user.email?.split('@')[0],coins:0};premiumLoad();S.premium.coins=Number(S.profile?.coins??S.premium.coins??0);await loadPremiumInventory();
    if(S.profile?.premium_frame||S.profile?.premium_title||S.profile?.premium_effect||S.profile?.premium_theme||S.profile?.premium_background||S.profile?.premium_avatar){S.premium.active={...S.premium.active,frame:S.profile.premium_frame||S.premium.active.frame,title:S.profile.premium_title||S.premium.active.title,effect:S.profile.premium_effect||S.premium.active.effect,theme:S.profile.premium_theme||S.premium.active.theme,background:S.profile.premium_background||S.premium.active.background,avatar:S.profile.premium_avatar||S.premium.active.avatar,badge:S.profile.premium_badge||S.premium.active.badge};premiumSave();}
    await loadUserTitles(S.user.id);S.isAdmin=String(S.profile?.role||'').toLowerCase()==='admin';
  }
  async function sendFriend(username){if(!sb||!username)return;const {data,error}=await sb.rpc('send_friend_request',{p_username:username.trim()});if(error)alert(error.message);else{alert(data?.existing?'Esse jogador já possui uma relação de amizade/solicitação com você.':'Solicitação enviada.');S.friendRows=null;go('friends')}}
  async function acceptFriend(id){const {error}=await sb.from('friendships').update({status:'accepted'}).eq('id',id).eq('addressee_id',S.user.id);if(error)alert(error.message);else{S.friendRows=null;go('friends')}}
  function support(){const rows=S.supportRows||[];return `<section class="support-page"><div class="title">💬 Suporte</div><p class="subtitle">Fale com a equipe do Q-Rival. Você pode sair do aplicativo e voltar sem perder a conversa.</p><div class="card pad"><div id="supportMessages" class="support-messages">${rows.length?rows.map(m=>`<div class="support-msg ${m.sender_id===S.user.id?'mine':''}"><div>${esc(m.message)}</div><small>${new Date(m.created_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</small></div>`).join(''):'<div class="muted center">Nenhuma mensagem ainda. Como podemos ajudar?</div>'}</div><form id="supportForm" class="chat-compose support-compose"><textarea id="supportInput" maxlength="1000" required rows="3" placeholder="Digite sua mensagem..."></textarea><button class="send-chat" type="submit">➤</button></form></div><button class="secondary" id="supportHome">← VOLTAR</button></section>`} 
  async function loadSupport(){if(!sb||!S.user)return;let {data:thread,error}=await sb.from('support_threads').select('id,status').eq('user_id',S.user.id).order('created_at',{ascending:false}).limit(1).maybeSingle();if(error)return console.warn(error);if(!thread){const r=await sb.from('support_threads').insert({user_id:S.user.id}).select('id,status').single();if(r.error)return console.warn(r.error);thread=r.data}S.supportThread=thread;const r=await sb.from('support_messages').select('id,thread_id,sender_id,message,created_at').eq('thread_id',thread.id).order('created_at',{ascending:true});if(!r.error)S.supportRows=r.data||[];if(S.realtime)sb.removeChannel(S.realtime);S.realtime=sb.channel('support-'+thread.id).on('postgres_changes',{event:'INSERT',schema:'public',table:'support_messages',filter:`thread_id=eq.${thread.id}`},payload=>{if(!S.supportRows.some(x=>x.id===payload.new.id)){S.supportRows.push(payload.new);if(S.route==='support')render()}}).subscribe();if(S.route==='support')render()}
  async function sendSupport(){const input=$('#supportInput');const message=input?.value.trim();if(!message||!S.supportThread)return;const {error}=await sb.from('support_messages').insert({thread_id:S.supportThread.id,sender_id:S.user.id,message});if(error)alert(error.message);else{input.value='';await loadSupport()}}
  async function loadAdminSupport(){if(!sb||!S.isAdmin)return;const {data,error}=await sb.from('support_threads').select('id,user_id,status,created_at,updated_at,profiles(username,display_name)').order('updated_at',{ascending:false});if(!error)S.supportAdminRows=data||[]}
  async function loadAdminSupportMessages(threadId){const {data,error}=await sb.from('support_messages').select('id,thread_id,sender_id,message,created_at').eq('thread_id',threadId).order('created_at',{ascending:true});return error?[]:(data||[])}
  async function openAdminSupportChat(threadId){if(!sb||!threadId)return;S.supportAdminThreadId=threadId;S.supportAdminMessages=await loadAdminSupportMessages(threadId);render();setTimeout(()=>{const el=document.querySelector('.support-admin-messages');if(el)el.scrollTop=el.scrollHeight;},0)}
  async function adminSupportReply(threadId){return openAdminSupportChat(threadId)}
  async function sendAdminSupportMessage(){const input=$('#adminSupportInput');const msg=input?.value.trim();if(!msg||!S.supportAdminThreadId)return;const {error}=await sb.from('support_messages').insert({thread_id:S.supportAdminThreadId,sender_id:S.user.id,message:msg});if(error)return alert(error.message);input.value='';await sb.from('support_threads').update({status:'open',updated_at:new Date().toISOString()}).eq('id',S.supportAdminThreadId);S.supportAdminMessages=await loadAdminSupportMessages(S.supportAdminThreadId);await loadAdminSupport();render();setTimeout(()=>{const el=document.querySelector('.support-admin-messages');if(el)el.scrollTop=el.scrollHeight;},0)}
    function chat(){const name=S.chatTarget?.username||'Amigo';const rows=S.chatRows||[];return `<div class="title chat-title">💬 ${esc(name)}</div><div class="card chat-box"><div id="chatMessages" class="chat-messages">${rows.length?rows.map(m=>{const mine=m.sender_id===S.user.id;const photo=m.message_type==='photo'&&m.media_url;return `<div class="chat-msg ${mine?'mine':''}"><div class="bubble">${photo?`<img src="${esc(m.media_url)}" class="chat-photo" alt="Foto enviada">`:`<div>${esc(m.message)}</div>`}<small>${new Date(m.created_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</small></div></div>`}).join(''):'<div class="muted center">Nenhuma mensagem ainda. Diga oi 👋</div>'}</div>${S.chatTyping?'<div class="chat-typing">✍️ digitando...</div>':''}${S.emojiOpen?`<div class="emoji-panel">${['😀','😂','😍','😎','🥳','👍','❤️','🔥','👏','😢','😡','🤔','🎉','💪','🙏','👋','🤣','😘','💯','⚡'].map(e=>`<button type="button" class="emoji-btn" data-emoji="${e}">${e}</button>`).join('')}</div>`:''}<form id="chatForm" class="chat-compose"><button type="button" class="chat-tool" id="emojiBtn">😊</button><label class="chat-tool" for="chatPhoto">📷</label><input id="chatPhoto" type="file" accept="image/*" hidden><input id="chatInput" maxlength="500" autocomplete="off" placeholder="Digite uma mensagem..."><button class="send-chat" type="submit">➤</button></form></div><button class="secondary" id="backFriends">← VOLTAR AOS AMIGOS</button>`}
  async function openChat(id,name){if(!sb||!id)return;S.chatTargetId=id;S.chatTarget={id,username:name};S.chatTyping=false;const {data,error}=await sb.from('direct_messages').select('id,sender_id,receiver_id,message,message_type,media_url,created_at').or(`and(sender_id.eq.${S.user.id},receiver_id.eq.${id}),and(sender_id.eq.${id},receiver_id.eq.${S.user.id})`).order('created_at',{ascending:true});if(error)return alert(error.message);S.chatRows=data||[];if(S.realtime)sb.removeChannel(S.realtime);S.realtime=sb.channel(`chat-${[S.user.id,id].sort().join('-')}`).on('postgres_changes',{event:'INSERT',schema:'public',table:'direct_messages'},payload=>{const m=payload.new;if((m.sender_id===S.user.id&&m.receiver_id===id)||(m.sender_id===id&&m.receiver_id===S.user.id)){if(!S.chatRows.some(x=>x.id===m.id)){S.chatRows.push(m);render();}}}).on('broadcast',{event:'typing'},payload=>{if(payload.payload?.user_id===id){S.chatTyping=!!payload.payload.typing;if(S.route==='chat')render();clearTimeout(S.chatTypingTimer);if(S.chatTyping)S.chatTypingTimer=setTimeout(()=>{S.chatTyping=false;render()},1800)}}).subscribe();go('chat')}
  async function sendTyping(){if(!S.realtime||!S.chatTargetId||!S.user)return;clearTimeout(S.chatTypingTimer);S.realtime.send({type:'broadcast',event:'typing',payload:{user_id:S.user.id,typing:true}});S.chatTypingTimer=setTimeout(()=>S.realtime?.send({type:'broadcast',event:'typing',payload:{user_id:S.user.id,typing:false}}),1200)}
  async function sendChat(){const text=$('#chatInput')?.value.trim();if(!text||!S.chatTargetId)return;const {error}=await sb.from('direct_messages').insert({sender_id:S.user.id,receiver_id:S.chatTargetId,message:text,message_type:'text'});if(error)alert(error.message);else{$('#chatInput').value='';S.emojiOpen=false;await openChat(S.chatTargetId,S.chatTarget.username)}}
  async function sendChatPhoto(file){if(!file||!S.chatTargetId)return;if(file.size>5*1024*1024)return alert('A foto deve ter no máximo 5 MB.');const ext=(file.name.split('.').pop()||'jpg').toLowerCase();const path=`${S.user.id}/${Date.now()}-${Math.random().toString(36).slice(2)}.${ext}`;const {error:up}=await sb.storage.from('chat-media').upload(path,file,{cacheControl:'3600',upsert:false,contentType:file.type});if(up)return alert(up.message);const {data}=sb.storage.from('chat-media').getPublicUrl(path);const {error}=await sb.from('direct_messages').insert({sender_id:S.user.id,receiver_id:S.chatTargetId,message:'📷 Foto',message_type:'photo',media_url:data.publicUrl});if(error)alert(error.message);else await openChat(S.chatTargetId,S.chatTarget.username)}
