  async function chooseChallengeCategory(category){const id=S.challengeTargetId;S.challengeModal=false;render();const {data,error}=await sb.rpc('create_friend_challenge',{p_friend_id:id,p_category:category});if(error)return alert(error.message);alert('⚔️ Desafio enviado! Você já pode jogar agora; seu amigo poderá responder quando entrar.');await openAsyncChallenge(data)}
